mapper.select:
select ri.id, ri.room_number, ri.rent, ri.apartment_id, ri.is_release, la.room_id is not null is_check_in, la.lease_end_date, ai.id apart_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release apart_is_release from room_info ri left join lease_agreement la on ri.id = la.room_id and la.is_deleted = 0 and la.status in (2,5) left join apartment_info ai on ri.apartment_id = ai.id and ai.is_deleted = 0
ri.is_deleted = 0
apart.province_id = #{queryVo.provinceId}
and apart.city_id = #{queryVo.cityId}
and apart.district_id = #{queryVo.districtId}
and apartment_id = #{queryVo.apartmentId}

select ri.id, ri.room_number, ri.rent, ai.id apartment_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release from room_info ri left join apartment_info ai on ri.apartment_id = ai.id and ai.is_deleted = 0
ri.is_deleted = 0 and ri.is_release = 1 and ri.id not in( select room_id from lease_agreement where is_deleted = 0 and status in (2,5) )
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and (ri.rent between #{queryVo.minRent} and #{queryVo.maxRent})
and ri.id in ( select room_id from room_payment_type where is_deleted = 0 and payment_type_id = #{queryVo.paymentTypeId} )
order by ri.rent ${queryVo.orderType}
